import numpy as np

# A high-quality sign matrix found by determinant-guided single-entry ascent.
_ROWS = ['00101110110100110001010000110', '00001111011010011000101000011', '00001011101001001100010100100', '00010101100100101010101000100', '01001110111010000011100101100', '00110100010111001001110100101', '10010010101110100100110101011', '10001000000111010010011001101', '10000100001001100001001100010', '01000010010101110000100110101', '10000101110010111000010111000', '00010010110001011101001001000', '00101000000010111110100101110', '00000100001000010111110010001', '10101011000100001001100011000', '11010111000010010101111100100', '01100010100011000010111010010', '00110011010000100011011101001', '10111000111000010000101110100', '01011100010100000100011111010', '01100110001010101100001011101', '00110111001111010010000111110', '01011001100010000001000010111', '10100101110001000100100001111', '11010010011000001010010001110', '01100001011110000100000000000', '11111110100000011010000100001', '10011110010011100110000010000', '01111101001001110000110001000']

def construct_hadamard_matrix(n=29):
    if n != 29: raise ValueError("this construction is for n=29")
    return np.array([[1 if c == "1" else -1 for c in s] for s in _ROWS], dtype=np.int8)

def run_code():
    return (construct_hadamard_matrix(),)
